import test from 'node:test';
import assert from 'node:assert/strict';
import {createRequire} from 'node:module';
import {readFile,stat} from 'node:fs/promises';
import vm from 'node:vm';
const root=new URL('../',import.meta.url);
globalThis.document={createElement:()=>({relList:{supports:()=>true}})};
const e=createRequire(import.meta.url)('../.build/engine.cjs');
const time=Date.parse('2026-09-29T10:00:00Z');
const run=(state,action)=>e.reducer(state,{now:time,...action});
const scenarios=['search','booked','prepare','stay','checkout','after','family','business','stay-family','stay-business','stay-pet','after-business','issue','issue-resolved','assistant','friends','stories','together','story-offer','story-expired','hotel-chat','hotel-chats','new-hotel-chat','hotel-staff','bonuses','guest','find','swipe','map','prices','guests','change-booking','cancel-booking','cancel-penalty','order','order-alternative','order-completed','reservation','reservation-payment','reservation-success','payment-retry','profile-details'];
for(const name of scenarios)test(`original scenario: ${name}`,()=>{
 const s=e.initial(name,time);assert.ok(s.navigation);assert.ok(s.booking);assert.ok(s.search);assert.equal(e.hotel(s.booking.hotelId).id,s.booking.hotelId);assert.doesNotThrow(()=>JSON.stringify(s));
});
test('search, navigation and back',()=>{let s=e.initial('search',time);s=run(s,{type:'SEARCH_SUBMIT',city:'Сочи'});assert.equal(s.search.results,true);s=run(s,{type:'OPEN',screen:{type:'hotel',hotelId:'more'}});assert.equal(s.navigation.screen.type,'hotel');s=run(s,{type:'BACK'});assert.equal(s.navigation.screen,null);});
test('checkin and digital key depend on stay state',()=>{let s=e.initial('booked',time);s=run(s,{type:'KEY_OPEN'});assert.equal(s.booking.keyOpened,false);s=e.initial('stay',time);s=run(s,{type:'KEY_OPEN'});assert.equal(s.booking.keyOpened,true);});
test('service request progresses to completion',()=>{let s=e.initial('stay',time);const count=s.orders.length;s=run(s,{type:'ORDER_PLACE',id:'towels'});assert.equal(s.orders.length,count+1);s=run(s,{type:'MOCK_PROGRESS',now:time+600000});s=run(s,{type:'MOCK_PROGRESS',now:time+1200000});assert.equal(s.orders.at(-1).status,'Выполнен');});
test('cancellation produces refund state',()=>{let s=e.initial('booked',time);s=run(s,{type:'BOOKING_CANCEL_CONFIRM',bookingId:s.booking.id,revision:s.booking.revision});assert.ok(s.booking.cancellation);assert.ok(s.booking.refunds.length);});
test('booking changes can be quoted and confirmed',()=>{let s=e.initial('booked',time);s=run(s,{type:'BOOKING_CHANGE',value:{arrival:'2026-09-24',departure:'2026-09-28',party:s.booking.party}});assert.ok(s.booking.changeRequest);s=run(s,{type:'BOOKING_CHANGE_CONFIRM',quoteId:s.booking.changeRequest.id});assert.equal(s.booking.arrival,'2026-09-24');});
test('payment failure can be retried successfully',()=>{let s=e.initial('payment-retry',time);s=run(s,{type:'RESERVATION_PAY',draftId:s.reservation.id});s=run(s,{type:'MOCK_PROGRESS',now:time+600000});assert.equal(s.reservation.status,'failed');s=run(s,{type:'RESERVATION_PAY',draftId:s.reservation.id,now:time+700000});s=run(s,{type:'MOCK_PROGRESS',now:time+900000});assert.equal(s.reservation.status,'confirmed');assert.equal(s.navigation.screen.type,'reservation-success');});
test('checkout credits bonus points only once',()=>{let s=e.initial('checkout',time);const old=s.loyalty.balance;s=run(s,{type:'CHECKOUT_COMPLETE'});assert.ok(s.loyalty.balance>old);const balance=s.loyalty.balance;s=run(s,{type:'CHECKOUT_COMPLETE'});assert.equal(s.loyalty.balance,balance);});
test('assistant and hotel chat reply locally',()=>{let s=e.initial('stay',time);s=run(s,{type:'CHAT_SEND',text:'Хотим тихий отель со спа у моря'});assert.ok(s.chat.discovery.some(m=>m.sender==='ai'));s=run(s,{type:'HOTEL_CHAT_SEND',hotelId:'more',text:'Во сколько завтрак?'});s=run(s,{type:'MOCK_PROGRESS',now:time+600000});assert.ok(s.chat.conversations.more.messages.some(m=>m.sender==='ai'&&m.text));});
test('all original hotel photographs, service images, fonts and videos exist locally',async()=>{
 const report=JSON.parse(await readFile(new URL('source/asset-report.json',root),'utf8'));assert.equal(report.failures.length,0);
 for(const p of report.files.filter(p=>!p.endsWith('.js')&&!p.endsWith('.css')))assert.ok((await stat(new URL('dist'+p,root))).size>0,p);
 assert.equal(e.hotels.length,30);
});
async function apiContext(){
 const storage=new Map();const context=vm.createContext({URL,Response,EventTarget,Event,crypto:globalThis.crypto,queueMicrotask,console,localStorage:{getItem:k=>storage.get(k),setItem:(k,v)=>storage.set(k,v),removeItem:k=>storage.delete(k)}});
 const script=await readFile(new URL('.build/runtime.js',root),'utf8');vm.runInContext(script,context);context.PoraDemo.engine=e;return context;
}
async function login(c,id='alexander'){const d=c.PoraDemo.api('/api/v1/auth/demo/request-code','POST',{personaId:id});return c.PoraDemo.api('/api/v1/auth/demo/verify-code','POST',{challengeId:d.challengeId,code:'123456'});}
test('local authentication, invalid code and logout',async()=>{const c=await apiContext();assert.equal(c.PoraDemo.api('/api/v1/auth/bootstrap').user,null);const challenge=c.PoraDemo.api('/api/v1/auth/demo/request-code','POST',{personaId:'anya'});assert.equal(c.PoraDemo.api('/api/v1/auth/demo/verify-code','POST',{challengeId:challenge.challengeId,code:'000000'}).error.code,'INVALID_CODE');assert.equal((await login(c,'anya')).user.firstName,'Аня');c.PoraDemo.api('/api/v1/auth/logout','POST');assert.equal(c.PoraDemo.api('/api/v1/auth/bootstrap').user,null);});
test('favorites persist and are isolated between demo accounts',async()=>{const c=await apiContext();await login(c);c.PoraDemo.api('/api/v1/favorites','POST',{hotelId:'more',saved:true});assert.equal(c.PoraDemo.api('/api/v1/favorites/ids').ids[0],'more');await login(c,'anya');assert.equal(c.PoraDemo.api('/api/v1/favorites/ids').ids.length,0);await login(c);assert.equal(c.PoraDemo.api('/api/v1/favorites').items[0].hotel.name,'Swissôtel Камелия');});
test('documents CRUD masks entered number',async()=>{const c=await apiContext();await login(c);const d=c.PoraDemo.api('/api/v1/documents','POST',{name:'Демо Гость',kind:'passport',number:'0000123456',birthDate:'1990-01-01'});assert.equal(d.number,undefined);assert.equal(d.maskedNumber,'•••• 3456');c.PoraDemo.api('/api/v1/documents/'+d.id,'PATCH',{name:'Новый Гость'});assert.equal(c.PoraDemo.api('/api/v1/documents').items[0].name,'Новый Гость');c.PoraDemo.api('/api/v1/documents/'+d.id+'/remove','POST');assert.equal(c.PoraDemo.api('/api/v1/documents').items.length,0);});
test('shared collections, hotel votes and members',async()=>{const c=await apiContext();await login(c);const coll=c.PoraDemo.api('/api/v1/social/collections','POST',{title:'Море',memberIds:['anya'],hotelIds:['more']});assert.equal(coll.members.length,2);let v=c.PoraDemo.api('/api/v1/social/collections/'+coll.id+'/vote','POST',{hotelId:'more',liked:true});assert.equal(v.items[0].votes.length,1);v=c.PoraDemo.api('/api/v1/social/collections/'+coll.id+'/hotels','POST',{hotelId:'more',present:false});assert.equal(v.items.length,0);});
test('trip history follows original scenario and local notes',async()=>{const c=await apiContext();await login(c);c.PoraDemo.saveTrip(e.initial('stay',time));const trip=c.PoraDemo.api('/api/v1/trips?filter=upcoming&on=2026-09-24').items[0];assert.ok(trip);const result=c.PoraDemo.api('/api/v1/trips/'+trip.id+'/note','POST',{note:'Приеду вечером'});assert.equal(result.booking.note,'Приеду вечером');});
test('fetch is local and blocks external requests',async()=>{const c=await apiContext();assert.equal((await c.fetch('/api/v1/auth/bootstrap')).status,200);assert.equal((await c.fetch('https://test.llmteam.tech/')).status,503);});
test('classic bundle and local styles support direct opening',async()=>{const html=await readFile(new URL('dist/index.html',root),'utf8');assert.ok(!html.includes('type="module"'));assert.ok(html.includes('connect-src \'none\''));assert.ok(html.includes('src="./assets/app.js"'));assert.ok(!html.includes('href="/'));assert.ok(html.includes('--color-brand'));});
